#include <bits/stdc++.h>
using namespace std;

// 自写 gcd，兼容老标准
static inline int mygcd(int a, int b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) { int t = a % b; a = b; b = t; }
    return a;
}

long long min_sum_after_ops(int n, const vector<int>& a) {
    long long ans = 0;
    int l = 1;
    while (l <= n) {
        int q = n / l;
        int r = n / q;           // 同一组的右端点
        int g = 0;
        for (int i = l - 1; i <= r - 1; ++i) {
            g = (g == 0) ? a[i] : mygcd(g, a[i]); // 用自写 gcd
        }
        ans += 1LL * (r - l + 1) * g;
        l = r + 1;
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        int n;
        cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i];
        cout << min_sum_after_ops(n, a) << "\n";
    }
    return 0;
}
